def boxes(g):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and g[i][j] not in seen:
                c=g[i][j]; stack=[(i,j)]; comp=[]; seen.add((i,j))
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                ys=[a for a,b in comp]; xs=[b for a,b in comp]
                h,w=max(ys)-min(ys)+1,max(xs)-min(xs)+1
                if len(comp)==2*(h+w)-4:  # hollow rectangle
                    out.append((c,min(ys),min(xs),h,w))
    return out

def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    bx=boxes(g)
    bcols=sorted([b[0] for b in bx],reverse=True)
    cellcols=sorted(set(g[i][j] for i in range(H) for j in range(W) if g[i][j] and (i,j) not in {(y,x) for c,r0,c0,h,w in bx for y in range(r0,r0+h) for x in range(c0,c0+w)}))
    m=dict(zip(bcols,cellcols))
    for c,r0,c0,h,w in bx:
        fc=m[c]
        for y in range(r0+1,r0+h-1):
            for x in range(c0+1,c0+w-1):
                if (y-x-(r0+1-c0-1))%2==0: g[y][x]=fc
    return g

